// Structure career insights
const aiResponse = $json.message.content;
let insights;

try {
  const jsonMatch = aiResponse.match(/\{[\s\S]*\}/);
  insights = jsonMatch ? JSON.parse(jsonMatch[0]) : {};
} catch (e) {
  insights = { error: 'Failed to parse' };
}

// Add metadata
insights.role = $json.body.role;
insights.generated_at = new Date().toISOString();
insights.source = 'ai_powered_with_market_data';
insights.country = $json.body.country || 'Global';

return {
  json: insights
};
